export type LiveVehicleStatus = typeof LiveVehicleStatus[keyof typeof LiveVehicleStatus];


export const LiveVehicleStatus = {
  AVAILABLE: 'AVAILABLE',
  RESERVED: 'RESERVED',
  SOLD: 'SOLD',
  REMOVED: 'REMOVED',
  UNKNOWN: 'UNKNOWN',
} as const;

export interface LiveVehicle {
  /**
     * 17-character VIN if available from the provider
     * @nullable
     */
  vin?: string | null;
  /** Provider-specific listing identifier */
  listingId: string;
  /** @nullable */
  make?: string | null;
  /** @nullable */
  model?: string | null;
  /** @nullable */
  year?: number | null;
  /**
     * Odometer reading in provider-native units
     * @nullable
     */
  mileage?: number | null;
  /**
     * Asking price in provider-native currency units
     * @nullable
     */
  price?: number | null;
  /**
     * ISO 4217 currency code (e.g. KRW, USD)
     * @nullable
     */
  currency?: string | null;
  /** @nullable */
  fuel?: string | null;
  /** @nullable */
  transmission?: string | null;
  /** @nullable */
  drivetrain?: string | null;
  /** @nullable */
  location?: string | null;
  /** @nullable */
  country?: string | null;
  /** Photo URLs provided by the upstream source */
  photos?: string[];
  /**
     * Direct URL to the listing on the provider's platform
     * @nullable
     */
  listingUrl?: string | null;
  status: LiveVehicleStatus;
  /** @nullable */
  createdDate?: string | null;
  /** @nullable */
  updatedDate?: string | null;
  /** @nullable */
  soldDate?: string | null;
}

export interface LivePublicProvider {
  id: number;
  /** Display name (e.g. KB ChaChaCha Live) */
  name: string;
  /** Adapter key used as the `provider` query parameter (`encar_live`, `autowini_live`, `kbchachacha_live`) */
  internalName: string;
}

export interface LiveVehicleListData {
  vehicles: LiveVehicle[];
  /** Total matching records (before pagination) */
  total: number;
  limit: number;
  offset: number;
  /** Whether this response was served from the PostgreSQL cache */
  cached: boolean;
  /**
     * When the cached entry was created (null if not cached)
     * @nullable
     */
  cachedAt?: string | null;
  provider: LivePublicProvider;
}

export interface LiveVehicleListEnvelope {
  success: true;
  data: LiveVehicleListData;
}

export interface LiveVehicleEnvelope {
  success: true;
  data: LiveVehicle;
  cached: boolean;
  /** @nullable */
  cachedAt?: string | null;
  provider?: LivePublicProvider;
}

export interface LivePublicProviderListEnvelope {
  success: true;
  data: LivePublicProvider[];
}

